function conv2d(a: Image, k: Image) { const h = a.length - k.length + 1, w = a[0].length - k[0].length + 1, out = Array.from({ length: h }, () => Array(w).fill(0)); for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) { let s = 0; for (let j = 0; j < k.length; j++) for (let i = 0; i < k[0].length; i++) s += a[y + j][x + i] * k[j][i]; out[y][x] = Math.max(0, s); } return out; }
