// Public registry used by the museum shell.  Factories are intentionally
// lazy-friendly: each call returns a fresh deterministic experiment instance.
export const modernExperimentFactories: Record<string, () => ExperimentInstance> = {
  'k-means': () => new KMeansExperiment(),
  'decision-tree': () => new DecisionTreeExperiment(),
  'chess-search': () => new ChessSearchExperiment(),
  mcts: () => new MctsExperiment(),
  cnn: () => new CnnExperiment(),
  gan: () => new GanExperiment(),
  transformer: () => new TransformerExperiment(),
  autoregressive: () => new AutoregressiveExperiment(),
  diffusion: () => new DiffusionExperiment(),
  'world-model': () => new WorldModelExperiment(),
};
export const modernExperiments: ExperimentInstance[] = Object.values(modernExperimentFactories).map(f => f());
export const modernDefinitions: ExperimentDefinition[] = modernExperiments.map(e => e.definition);
export const modernRegistry: ExperimentRegistryEntry[] = modernDefinitions.map(d => ({ ...d, create: modernExperimentFactories[d.id] }));
